USE [master];SET NOCOUNT ON;SET XACT_ABORT ON;DECLARE @R varchar(20)='$(RunToken)',@T sysname=N'$(TargetDatabase)',@S nvarchar(max),@C int=CASE TRY_CONVERT(int,SERVERPROPERTY('ProductMajorVersion')) WHEN 15 THEN 150 WHEN 16 THEN 160 WHEN 17 THEN 170 END;IF '$(DemoId)'<>'STL-009' OR @T<>N'SQLPERF_LAB_STL009_'+@R OR @C IS NULL THROW 51000,'FAIL_CONTRACT: STL-009-Setupziel ist ungueltig.',1;IF DB_ID(@T) IS NOT NULL THROW 51002,'FAIL_STATE: STL-009-Zieldatenbank existiert.',1;SET @S=N'CREATE DATABASE '+QUOTENAME(@T)+N';ALTER DATABASE '+QUOTENAME(@T)+N' SET RECOVERY SIMPLE;ALTER DATABASE '+QUOTENAME(@T)+N' SET COMPATIBILITY_LEVEL='+CONVERT(nvarchar(3),@C)+N';';EXEC(@S);SET @S=N'USE '+QUOTENAME(@T)+N';EXEC sys.sp_addextendedproperty @name=N''SQLPERF.Project'',@value=N''SQL_PerformanceSchulung'';EXEC sys.sp_addextendedproperty @name=N''SQLPERF.ContractVersion'',@value=N''1.0'';EXEC sys.sp_addextendedproperty @name=N''SQLPERF.DemoId'',@value=N''STL-009'';EXEC sys.sp_addextendedproperty @name=N''SQLPERF.RunToken'',@value=@R;';EXEC sys.sp_executesql @S,N'@R varchar(20)',@R=@R;
GO
USE [$(TargetDatabase)];IF SCHEMA_ID(N'lab') IS NULL EXEC(N'CREATE SCHEMA lab AUTHORIZATION dbo;');CREATE TABLE lab.CommitRows(RowId int PRIMARY KEY,Payload char(200) NOT NULL);CREATE TABLE lab.Evidence(Stage varchar(16) PRIMARY KEY,NumWrites bigint NOT NULL,BytesWritten bigint NOT NULL,WriteLogWaitMs bigint NOT NULL,ResultRows bigint NOT NULL,ResultChecksum int NOT NULL);PRINT 'SQLPERF_SUMMARY|PASS|OK';
